| Detective Type | Onverschrokken PI, cynisch | Amateur speurder | Briljante detective | Professionele agent |
| Geweld Niveau | Geïmpliceerd, atmosferisch | Off-screen | Minimaal | Gedetailleerd |
| Sociaal Commentaar | Sterk (corruptie, klasse) | Gematigd | Minimaal | Gematigd |
| Personage Complexiteit | Moreel grijs | Over het algemeen goed | Duidelijke rollen | Professioneel |
