## クイックスタートビクトリア朝ミステリーチェックリスト

ビクトリア朝のマーダーミステリーパーティーを準備する方法は次のとおりです。

• シーンを設定します：ろうそくの明かり、暗い布、ビクトリア朝の小道具で空間を変換します
• カスタムキャラクターを作成します：友人の性格と興味に一致する役割をデザインします
• 時代の手がかりを開発します：電報、毒の瓶、相続文書、新聞の切り抜きを使用します
• タイムラインを計画します：30分の社交期間、劇的な殺人の啓示、90分の捜査、クライマックスの解決
• 衣装をデザインします：懐中時計やレースの手袋などのアクセサリー付きのビクトリア朝の正装
• 本格的な食べ物を準備します：シェリーやポートなどの時代の飲み物を含むマルチコースディナー
• 説得力のある背景を書きます：階級の緊張や家族のスキャンダルなどのビクトリア朝特有の対立を含めます
• 雰囲気のある音楽を作成します：ショパン、リストからの古典的な曲と劇的なオルガン音楽

