あなたのグループのフロンティアアドベンチャーへの愛に完璧に合わせたワイルドウェスト殺人ミステリーパーティーを作成したいですか？すべての空間を埃っぽいフロンティアタウンに変える本格的なフロンティア正義体験をデザインしましょう。

忘れられないワイルドウェスト殺人ミステリーパーティーを主催するために、友人の性格を反映するカスタムアウトローと法執行官のキャラクターを作成し、サルーン設定と西部小道具でフロンティア雰囲気を確立し、指名手配ポスターと電報メッセージなどのフロンティア技術を使用した手がかりを開発し、牛泥棒、金鉱紛争、フロンティア正義などのオールドウェストの対立に根ざしたストーリーラインを作成します。

